    user_id INT PRIMARY KEY,
    name VARCHAR(255),
    mail VARCHAR(255)
);

solutions.query:
SELECT user_id, name, mail
FROM Users
WHERE mail REGEXP '^[a-zA-Z][a-zA-Z0-9._-]*@leetcode\\.com$';

